import{_ as c,l as d,o as e,c as p,v as r,p as s,x as t,d as i,i as l,S as n}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"PEG 与 packrat","description":"","frontmatter":{"title":"PEG 与 packrat","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/peg-packrat.md","filePath":"cs/peg-packrat.md","lastUpdated":1789023840000}'),P={name:"cs/peg-packrat.md"};function E(h,a,G,_,k,m){const o=d("Mermaid");return e(),p("div",null,[a[1]||(a[1]=r('<h1 id="peg-与-packrat" tabindex="-1">PEG 与 packrat <a class="header-anchor" href="#peg-与-packrat" aria-label="Permalink to &quot;PEG 与 packrat&quot;">​</a></h1><div class="epigraph"><p>有序选择不是并：先试左边，成功则右边永不发生。记忆化后线性时间，但 Peg 的语言类与 CFG 交叉而不包含。</p><footer>—— 据 Ford, Parsing Expression Grammars, 2004；Ford, Packrat Parsing, 2002 整理</footer></div><p>上一课<a href="/cs/glr-parser">GLR</a>在 CFG 上保留全部推导。缺口是另一套前端习惯：<strong>PEG</strong>——<code>e1 / e2</code> 有序，且带 <code>&amp;</code>/<code>!</code> 谓词。packrat：每个位置、每个非终结符只算一次，线性于输入×规则。本课钉与 CFG 的差，不把 PEG 写成「更现代的 yacc」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CFG 的 <code>|</code> 是并，二义来自多条同时成功。PEG 的 <code>/</code>：左枝吃掉则右枝不看。左递归在朴素 PEG 里会无限递归，需改写或特殊处理。缺口是<strong>有序选择与谓词</strong>，不是再填 LALR 表。</p><p>packrat 用表记住 <code>(i, A)</code> 的成败与消耗长度，避免递归下降的指数。空间 \\(O(n\\cdot |G|)\\)，这是换时间的代价。</p><h3 id="不是" tabindex="-1"><code>/</code> 不是 <code>|</code> <a class="header-anchor" href="#不是" aria-label="Permalink to &quot;`/` 不是 `|`&quot;">​</a></h3><p><code>A / A B</code> 永远认短的 <code>A</code>，后面的 <code>B</code> 不是「另一条合法产生式」。把 yacc 文法机械换成 PEG 会静默改变语言。最长匹配要显式写成优先长枝，或用谓词。</p><p><span class="marginnote">Ford 2004 POPL（PEG）；2002 ICFP（packrat）。PEGs 不能直接搬 CYK 的「成员 = 某非终结符推出」。本课不引用不存在的 arXiv 编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>手写或生成递归下降，每个解析函数对位置做记忆化。谓词 <code>&amp;e</code> 成功不消耗；<code>!e</code> 失败则成功。词法可并进同一 PEG，空白用显式规则吃掉——与 lex/yacc 分阶段对照，不是必须合一。</p>',11)),(e(),s(n,null,{default:t(()=>[l(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEG%5B%22%E6%9C%89%E5%BA%8F%E8%A7%84%E5%88%99%22%5D%20--%3E%20RD%5B%22%E9%80%92%E5%BD%92%E4%B8%8B%E9%99%8D%22%5D%0A%20%20RD%20--%3E%20MEM%5B%22packrat%20%E8%A1%A8%22%5D%0A%20%20MEM%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>工具链（如许多 PEG 生成器）默认无左递归；需要左结合表达式时用 Pratt 或循环，下一课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>PEG 认的语言类与 CFG 不可比：有的 PEG 不是 CFG，有的 CFG 没有等价 PEG。间接左递归同样危险。错误信息：有序选择会把失败吞进左枝，诊断比 LR 的「此处期望 FOLLOW」更绕，后课错误恢复再对照。</p><p>不要用 PEG 证明 CFL 性质：泵引理对 PEG 不直接适用。本进阶课要的是实现策略，不是再开自动机层级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GLL，不把 tree-sitter 的 GLR 方言说成 PEG。后课默认：PEG = 有序选择 + 可选 packrat；表达式优先级常另用 Pratt。下一课算符优先的手写分析。</p><p>无限前瞻谓词可使某些输入极慢，若未记忆化；packrat 压掉重复，压不掉「谓词每次扫很长」的常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEG 的 <code>/</code> 有序，语言不等于 CFG 并。</li><li>packrat 记忆化后线性，换空间。</li><li>不要把 yacc 文法直接当 PEG。</li><li>出处：Ford, 2002、2004。</li></ul>',9))])}const f=c(P,[["render",E]]);export{A as __pageData,f as default};
